SmartSqlMap.Select:
select cast(decision_id as nvarchar(36)) as decision_id, decision_key, name, category, description, decision_type, source_format, status, draft_version_tag, published_version_tag, tags, created_by, created_time, modified_by, modified_time from decision_definition
( decision_key like '%' + #{keyword} + '%' or name like '%' + #{keyword} + '%' )
and category = #{category}
and decision_type = #{decisionType}
and status = #{status}
order by modified_time desc, created_time desc offset #{offset} rows fetch next #{limit} rows only

SmartSqlMap.Update:
update decision_definition
decision_key = #{decisionKey}, name = #{name}, category = #{category}, description = #{description}, decision_type = #{decisionType}, source_format = #{sourceFormat}, status = #{status}, draft_version_tag = #{draftVersionTag}, published_version_tag = #{publishedVersionTag}, tags = #{tags}, modified_by = #{modifiedBy}, modified_time = #{modifiedTime}
where decision_id = cast(#{decisionId} as uniqueidentifier)
